-- Who uploaded each photo, so a review can only use its author's own photos (generated by drizzle-kit),
-- plus a backfill: every photo already on a review belongs to that review's author.
CREATE TABLE "photos" (
	"url" text PRIMARY KEY NOT NULL,
	"member_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
